/* EventsPRO speaker countdown: timestamps keep the clock independent of repaint rate. */
;(function (root) {
	'use strict'
	const MAX = 86400000
	const defaults = () => ({
		schema: 'eventspro-timer-v1',
		mode: 'down',
		outputVisible: true,
		backgroundAlpha: 1,
		showClock: false,
		showHours: false,
		showHundredths: false,
		end: 'stop',
		message: '',
		title: 'Speaker time',
		duration: 600000,
		remaining: 600000,
		deadline: null,
		running: false,
		laps: [],
