			if (!Number.isFinite(value[key])) throw Error('Invalid time.')
		if (
			value.duration < 1000 ||
			value.duration > MAX ||
			Math.abs(value.remaining) > MAX ||
			value.warning < 0 ||
			value.warning > MAX ||
			typeof value.running !== 'boolean' ||
			(value.running && !Number.isFinite(value.deadline))
		)
			throw Error('Time out of range.')
