		if (Array.isArray(value.laps))
			for (const lap of value.laps.slice(0, 100)) {
				if (!Number.isFinite(lap?.atMs) || lap.atMs < 0 || lap.atMs > MAX * 2 || lap.atMs < (laps.at(-1)?.atMs ?? 0))
					continue
				laps.push({
					atMs: Math.round(lap.atMs),
					splitMs: Math.round(lap.atMs - (laps.at(-1)?.atMs ?? 0)),
				})
			}
