			backgroundColor: color(value.backgroundColor, '#000000'),
			alertColors: value.alertColors !== false,
			showClock: value.showClock === true,
			showHours: value.showHours === true,
			showHundredths: value.showHundredths === true,
			end: value.end === 'continue' ? 'continue' : 'stop',
			mode: ['down', 'up', 'clock'].includes(value.mode) ? value.mode : 'down',
			message: String(value.message || '').slice(0, 160),
			title: String(value.title || 'Speaker time').slice(0, 100),
			duration: value.duration,
