				(hours ? String(h).padStart(2, '0') + ':' : '') +
				String(m).padStart(2, '0') +
				':' +
				String(sec).padStart(2, '0') +
				(hundredths ? '.' + String(ticks % 100).padStart(2, '0') : '')
