;(() => {
	'use strict'
	const KEY = 'eventspro-speaker-timer-v1:' + location.pathname.split('/').slice(0, -1).join('/'),
		C = EventsPROSpeakerTimer
	let revision = -1,
		last = '',
		control = '',
		busy = false,
		offset = 0,
		reclaim = false
	const bytes = new Uint8Array(32)
	crypto.getRandomValues(bytes)
	const client =
		sessionStorage.timerLANClient ||
		(sessionStorage.timerLANClient = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join(''))
	const api = async (body) => {
		const r = await fetch('api', {
			method: 'POST',
			headers: { 'Content-Type': 'application/json' },
			body: JSON.stringify(body),
			cache: 'no-store',
		})
		const data = await r.json()
		if (!r.ok)
			throw Object.assign(Error(data.error || 'Disconnected'), {
				status: r.status,
			})
		return data
	}
	function save(data) {
		revision = data.revision
		offset = Date.now() - data.serverNow
		const local = {
			...data.state,
			deadline: data.state.running ? data.state.deadline + offset : null,
		}
		last = JSON.stringify(local)
		if (localStorage.getItem(KEY) !== last) {
			localStorage.setItem(KEY, last)
			dispatchEvent(
				new StorageEvent('storage', {
					key: KEY,
					newValue: last,
					storageArea: localStorage,
				}),
			)
		}
		const badge = document.querySelector('#lan-status')
		if (badge)
			badge.textContent = data.remote.connected ? 'Remote paired: ' + data.remote.device : 'Companion connected'
		if (data.remote.connected) document.querySelector('#lan-pairing')?.close()
	}
	async function tick() {
		if (busy) return
		busy = true
		try {
			if (!control) {
				const d = await api({ op: 'owner', client })
				control = d.control
				if (reclaim) {
					const local = JSON.parse(localStorage.getItem(KEY) || last)
					const newOffset = Date.now() - d.serverNow
					save(
						await api({
							op: 'sync',
							client,
							revision: d.revision,
							changed: true,
							state: {
								...local,
								deadline: local.running ? local.deadline - newOffset : null,
							},
							presets: JSON.parse(localStorage.getItem(KEY + '-presets') || '[]'),
							messages: JSON.parse(localStorage.getItem(KEY + '-messages') || '[]'),
						}),
					)
					reclaim = false
				} else save(d)
			} else {
				const raw = localStorage.getItem(KEY) || last
				save(
					await api({
						op: 'sync',
						client,
						revision,
						changed: raw !== last,
						state: {
							...JSON.parse(raw),
							deadline: JSON.parse(raw).running ? JSON.parse(raw).deadline - offset : null,
						},
						presets: JSON.parse(localStorage.getItem(KEY + '-presets') || '[]'),
						messages: JSON.parse(localStorage.getItem(KEY + '-messages') || '[]'),
					}),
				)
			}
		} catch (e) {
			if (e.status === 403) {
				reclaim = !!control
				control = ''
				revision = -1
			}
			const b = document.querySelector('#lan-status')
			if (b) b.textContent = e.message
		} finally {
			busy = false
			setTimeout(tick, 250)
		}
	}
	const output = new URLSearchParams(location.search).get('nativeSpeaker') === '1'
	if (output) {
		;(async function poll() {
			try {
				save(await api({ op: 'read', client }))
			} catch {}
			setTimeout(poll, 500)
		})()
		return
	}
	function attach() {
		const target = document.querySelector('.st-header .suite-projects') || document.querySelector('.st-header')
		if (!target || document.querySelector('#lan-status')) return
		const badge = document.createElement('span')
		badge.id = 'lan-status'
		badge.role = 'status'
		badge.style.cssText = 'color:#83e8ab;padding:10px'
		badge.textContent = 'Connecting to Companion'
		const button = document.createElement('button')
		button.textContent = 'Mobile remote'
		button.onclick = () => {
			if (!control) return
			const dialog = document.createElement('dialog')
			dialog.id = 'lan-pairing'
			dialog.style.cssText = 'background:#14232c;color:white;border:1px solid #61727f;border-radius:12px;padding:24px'
			const label = document.createElement('h2')
			label.textContent = 'Scan with your phone'
			const qr = document.createElement('canvas'),
				close = document.createElement('button')
			close.textContent = 'Close'
			close.onclick = () => dialog.close()
			dialog.append(label, qr, close)
			dialog.addEventListener('close', () => dialog.remove())
			document.body.append(dialog)
			EventsPROTimerQR.render(qr, new URL('mobile.html#timer-remote=' + control, location.href).href)
			dialog.showModal()
		}
		target.append(badge, button)
	}
	new MutationObserver(attach).observe(document.documentElement, {
		subtree: true,
		childList: true,
	})
	attach()
	tick()
})()

mobile.js:
;(() => {
	'use strict'
	const I=globalThis.EventsPROI18n;
 const es={'remote.title':'Control de Timer','remote.scan':'Escanea el QR de Timer con la cámara del móvil.','remote.start':'Iniciar','remote.pause':'Pausar','remote.reset':'Restablecer','remote.clear':'Borrar mensaje','remote.paired':'Conectado con Timer','remote.offline':'La ventana de Timer está desconectada','remote.disconnected':'Desconectado: {error}','remote.connecting':'Conectando'};
 const en={'remote.title':'Timer control','remote.scan':'Scan the Timer QR code using your phone camera.','remote.start':'Start','remote.pause':'Pause','remote.reset':'Reset','remote.clear':'Clear message','remote.paired':'Paired with Timer','remote.offline':'The Timer window is disconnected','remote.disconnected':'Disconnected: {error}','remote.connecting':'Connecting'};
 I.register('es',es);I.register('en',en);I.bind(document.getElementById('mobile-title'),'remote.title');I.selector(document.getElementById('mobile-header'),{local:true});
 const paintLabel=(node,key,params)=>I.render(node,I.message(key,params));
 const control = /^#timer-remote=([a-f0-9]{64})$/.exec(location.hash)?.[1]
	const status = document.getElementById('status')
	paintLabel(status,'remote.connecting')
	if (!control) {
		paintLabel(status,'remote.scan')
		return
	}
	const api = async (body) => {
		const r = await fetch('api', {
			method: 'POST',
			headers: { 'Content-Type': 'application/json' },
			body: JSON.stringify({ ...body, control }),
			cache: 'no-store',
		})
		const data = await r.json()
		if (!r.ok) throw Error(data.error)
		return data
	}
	for (const [label, action, value] of [
		['remote.start', 'start'],
		['remote.pause', 'pause'],
		['remote.reset', 'reset'],
		['remote.clear', 'message/clear'],
		['−1 min', 'adjust', -60],
		['+1 min', 'adjust', 60],
	]) {
		const b = document.createElement('button')
		if(label.startsWith('remote.'))paintLabel(b,label);else b.textContent=label
		b.onclick = async () => {
			try {
				await api({ op: 'command', command: { action, value } })
			} catch (e) {
				status.textContent = e.message
			}
		}
		document.getElementById('buttons').append(b)
	}
	async function poll() {
		try {
			const data = await api({ op: 'read' })
			paintLabel(status,data.online?'remote.paired':'remote.offline')
			document.getElementById('time').textContent = data.display.text
			document.getElementById('speaker').textContent = data.display.title
			document.getElementById('message').textContent = data.display.message
		} catch (e) {
			paintLabel(status,'remote.disconnected',{error:e.message})
		}
		setTimeout(poll, 500)
	}
	poll()
})()
